def gf2_solve(data):
 rows=[]
 for (x,y),v in data.items():
  inp=bits6(x,y)+[1]
  for bit in range(5): rows.append((inp,bit,(v>>bit)&1))
 # per output
 outs=[]
 for bit in range(5):
  eq=[(sum(b<<i for i,b in enumerate(bits6(x,y)+[1])),(v>>bit)&1) for (x,y),v in data.items()]
  # gaussian
  piv={}; ok=True
  for mask,rhs in eq:
   while mask:
    p=mask.bit_length()-1
    if p in piv: mask^=piv[p][0];rhs^=piv[p][1]
    else: piv[p]=(mask,rhs);break
   if not mask and rhs:ok=False
  outs.append(ok)
 return outs
